def clamp(value, lo, hi):
    if value < lo:
        return lo
    if value > hi:
        return hi
    return value

def is_palindrome(s):
    normalized = ''.join(char.lower() for char in s if char.isalnum())
    return normalized == normalized[::-1]

def average(nums):
    if not nums:
        return None
    return float(sum(nums) / len(nums))

def safe_divide(a, b):
    if b == 0:
        raise ValueError('division by zero')
    return a / b

def flatten(nested):
    result = []
    stack = [iter(nested)]

    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue

        if isinstance(item, list):
            stack.append(iter(item))
        else:
            result.append(item)

    return result

import re


def parse_duration(s):
    match = re.fullmatch(r'(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?', s)
    if not match or not any(match.groups()):
        raise ValueError('Invalid duration string')
    hours, minutes, seconds = match.groups()
    return (
        int(hours or 0) * 3600
        + int(minutes or 0) * 60
        + int(seconds or 0)
    )
